async function adminDashboard(env,chatId,origin){
 await botApi(env,"sendMessage",{chat_id:chatId,text:"⚙️ Administration Mr XPRONOS Play\n\nCe menu est visible uniquement sur ton compte Telegram. Tu peux consulter les statistiques, modifier les textes du bot et gérer les modules de jeu.",reply_markup:adminKeyboard(origin)});
}
async function adminStats(env,chatId,origin){
 const [p,s,w,d]=await Promise.all([
  env.DB.prepare("SELECT COUNT(*) n,COALESCE(SUM(confirmed_xp),0) xp FROM players").first(),
  env.DB.prepare("SELECT COUNT(*) n FROM sync_receipts").first(),
  env.DB.prepare("SELECT COUNT(*) n FROM wheel_claims").first(),
  env.DB.prepare("SELECT COUNT(*) n FROM daily_claims").first()
 ]);
 await botApi(env,"sendMessage",{chat_id:chatId,text:"📊 Statistiques du jeu\n\n👥 Joueurs : "+p.n+"\n⭐ XP confirmés : "+p.xp+"\n🔄 Synchronisations : "+s.n+"\n🎡 Tours de roue confirmés : "+w.n+"\n🎁 Bonus quotidiens confirmés : "+d.n,reply_markup:{inline_keyboard:[[{text:"⚙️ Retour à l’administration",callback_data:"mrxp:admin:home"}]]}});
}
const ADMIN_EDITS={edit_welcome:{key:"welcome",label:"message d’accueil",limit:900},edit_description:{key:"description",label:"description « Que peut faire ce bot ? »",limit:512},edit_short:{key:"short_description",label:"description courte",limit:120}};
async function startBotAdminEdit(env,chatId,userId,edit){
 const item=ADMIN_EDITS[edit];
 if(!item)return;
 await env.DB.prepare("INSERT INTO bot_admin_pending(telegram_id,edit_key,expires_ms) VALUES(?,?,?) ON CONFLICT(telegram_id) DO UPDATE SET edit_key=excluded.edit_key,expires_ms=excluded.expires_ms").bind(String(userId),item.key,Date.now()+10*60*1000).run();
 const current=await getBotText(env,item.key,"");
 await botApi(env,"sendMessage",{chat_id:chatId,text:"✏️ Modifier "+item.label+"\n\nTexte actuel :\n"+current+"\n\nEnvoie maintenant le nouveau texte (maximum "+item.limit+" caractères). Tu as 10 minutes. Envoie /cancel pour annuler."});
}
async function submitAdminEdit(env,chatId,userId,text){
 const pending=await env.DB.prepare("SELECT edit_key,expires_ms FROM bot_admin_pending WHERE telegram_id=?").bind(String(userId)).first();
 if(!pending)return false;
 if(pending.expires_ms<Date.now()){
  await env.DB.prepare("DELETE FROM bot_admin_pending WHERE telegram_id=?").bind(String(userId)).run();
  await botApi(env,"sendMessage",{chat_id:chatId,text:"Modification expirée. Utilise /admin pour recommencer."});
  return true;
 }
 const limits={welcome:900,description:512,short_description:120};
 const limit=limits[pending.edit_key];
 if(!limit){await env.DB.prepare("DELETE FROM bot_admin_pending WHERE telegram_id=?").bind(String(userId)).run();return true}
 const value=String(text||"").trim();
 if(value.length<10||value.length>limit){
  await botApi(env,"sendMessage",{chat_id:chatId,text:"Le texte doit contenir entre 10 et "+limit+" caractères. Essaie à nouveau ou envoie /cancel."});
  return true;
 }
 if(pending.edit_key==="description")await botApi(env,"setMyDescription",{description:value});
 if(pending.edit_key==="short_description")await botApi(env,"setMyShortDescription",{short_description:value});
 await env.DB.prepare("INSERT INTO bot_settings(key,value,updated_ms) VALUES(?,?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_ms=excluded.updated_ms").bind(pending.edit_key,value,Date.now()).run();
 await env.DB.prepare("DELETE FROM bot_admin_pending WHERE telegram_id=?").bind(String(userId)).run();
 await botApi(env,"sendMessage",{chat_id:chatId,text:"✅ Modification enregistrée et appliquée.",reply_markup:{inline_keyboard:[[{text:"⚙️ Administration",callback_data:"mrxp:admin:home"}]]}});
 return true;
}
async function telegramWebhook(env,update,origin,ctx){
 const callback=update?.callback_query;
 if(callback){
  const fromId=String(callback.from?.id||"");
  const chat=callback.message?.chat;
  if(!chat||chat.type!=="private"||String(chat.id)!==fromId){
   await botApi(env,"answerCallbackQuery",{callback_query_id:callback.id,text:"Action indisponible."});
   return;
  }
  const action=String(callback.data||"");
  if(!action.startsWith("mrxp:admin:")){
   await botApi(env,"answerCallbackQuery",{callback_query_id:callback.id});
   return;
  }
  const admin=await isBotAdmin(env,fromId);
  await botApi(env,"answerCallbackQuery",{callback_query_id:callback.id,text:admin?"":"Accès réservé à l’administrateur.",show_alert:!admin});
  if(!admin)return;
  const task=action.slice("mrxp:admin:".length);
  if(task==="home")return adminDashboard(env,chat.id,origin);
  if(task==="stats")return adminStats(env,chat.id,origin);
  if(task==="features")return adminFeatures(env,chat.id,origin);
  if(task==="health")return adminBotHealth(env,chat.id,origin);
  if(task==="channels")return channelMissionDiagnostic(env,chat.id,origin);
  if(task.startsWith("toggle_"))return changeGameFeature(env,chat.id,origin,task.slice("toggle_".length));
  if(ADMIN_EDITS[task])return startBotAdminEdit(env,chat.id,fromId,task);
  if(task==="close")return botApi(env,"editMessageReplyMarkup",{chat_id:chat.id,message_id:callback.message.message_id,reply_markup:{inline_keyboard:[]}});
  return;
 }
 const msg=update?.message;
 if(!msg||msg.chat?.type!=="private")return;
 const fromId=String(msg.from?.id||"");
 const chatId=String(msg.chat?.id||"");
 if(!fromId||chatId!==fromId)return;
 const raw=String(msg.text||"").trim();
 if(!raw)return;
 const cmd=raw.match(/^\/([a-z]+)(?:@MrXpronosPlayBot)?(?:\s|$)/i)?.[1]?.toLowerCase()||"";
 if(cmd==="start"||cmd==="play"){
  const admin=await isBotAdmin(env,fromId);
  if(admin&&ctx?.waitUntil){const setup=await env.DB.prepare("SELECT status FROM telegram_setup_status WHERE id='onboarding-public-admin-v1'").first();if(setup?.status!=="VERIFIED")ctx.waitUntil(configureTelegramBot(env).catch(()=>{}))}
  const welcome=await getBotText(env,"welcome",PUBLIC_WELCOME);
  await botApi(env,"sendMessage",{chat_id:chatId,text:welcome,reply_markup:openGameKeyboard(origin,admin)});
  return;
 }
 const admin=await isBotAdmin(env,fromId);
 if(!admin){
  if(cmd==="help")await botApi(env,"sendMessage",{chat_id:chatId,text:"Pour jouer, appuie sur /start puis sur « Ouvrir l’application »."});
  return;
 }
 if(cmd==="admin"){if(ctx?.waitUntil){const setup=await env.DB.prepare("SELECT status FROM telegram_setup_status WHERE id=\'onboarding-public-admin-v1\'").first();if(setup?.status!=="VERIFIED")ctx.waitUntil(configureTelegramBot(env).catch(()=>{}))}return adminDashboard(env,chatId,origin)}
 if(cmd==="cancel"){
  await env.DB.prepare("DELETE FROM bot_admin_pending WHERE telegram_id=?").bind(fromId).run();
  await botApi(env,"sendMessage",{chat_id:chatId,text:"Modification annulée.",reply_markup:{inline_keyboard:[[{text:"⚙️ Administration",callback_data:"mrxp:admin:home"}]]}});
  return;
 }
 if(!cmd)await submitAdminEdit(env,chatId,fromId,raw);
}

async function configureTelegramBot(env){
  let status="FAILED",details="";
  try{
   const rows=(await env.DB.prepare("SELECT telegram_id FROM bot_admins").all()).results||[];
   if(rows.length!==1)throw Error("Expected exactly one approved admin account");
   const id=Number(rows[0].telegram_id);
   if(!Number.isSafeInteger(id)||id<=0)throw Error("Invalid approved admin ID");
   const allStart=[{command:"start",description:"Démarrer Mr XPRONOS Play"}];
   const adminCommands=[...allStart,{command:"admin",description:"Gérer le bot (administrateur)"}];
   await botApi(env,"setMyCommands",{scope:{type:"default"},commands:allStart});
   await botApi(env,"setMyCommands",{scope:{type:"all_private_chats"},commands:allStart});
   await botApi(env,"setMyCommands",{scope:{type:"all_group_chats"},commands:allStart});
   await botApi(env,"setMyCommands",{scope:{type:"chat",chat_id:id},commands:adminCommands});
   await botApi(env,"setChatMenuButton",{menu_button:{type:"commands"}});
   await botApi(env,"setChatMenuButton",{chat_id:id,menu_button:{type:"commands"}});
   await botApi(env,"setMyDescription",{description:await getBotText(env,"description",BOT_DESCRIPTION)});
   await botApi(env,"setMyShortDescription",{short_description:await getBotText(env,"short_description",BOT_SHORT_DESCRIPTION)});
   await botApi(env,"setWebhook",{
    url:"https://mrxpronos-play.cinecanaux-xpronos.workers.dev/telegram/webhook",
    secret_token:env.WEBHOOK_SECRET,
    allowed_updates:["message","callback_query"],
    drop_pending_updates:false
   });
   const [pub,privateCommands,wh,menu]=await Promise.all([
    botApi(env,"getMyCommands",{scope:{type:"all_private_chats"}}),
    botApi(env,"getMyCommands",{scope:{type:"chat",chat_id:id}}),
    botApi(env,"getWebhookInfo",{}),
    botApi(env,"getChatMenuButton",{})
   ]);
   if(pub.length!==1||pub[0]?.command!=="start")throw Error("Public commands are not start-only");
   if(privateCommands.length!==2||privateCommands[0]?.command!=="start"||privateCommands[1]?.command!=="admin")throw Error("Admin commands not scoped correctly");
   if(!wh?.url?.endsWith("/telegram/webhook")||!wh?.allowed_updates?.includes("callback_query"))throw Error("Webhook callback support not enabled");
   if(menu?.type!=="commands")throw Error("Global Telegram bot menu not reset to commands");
   status="VERIFIED";
  }catch(e){details=String(e?.message||e).slice(0,200)}
  await env.DB.prepare("INSERT INTO telegram_setup_status(id,status,bot_username,webhook_url,menu_type,error,updated_ms) VALUES(?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET status=excluded.status,bot_username=excluded.bot_username,webhook_url=excluded.webhook_url,menu_type=excluded.menu_type,error=excluded.error,updated_ms=excluded.updated_ms").bind("onboarding-public-admin-v1",status,"MrXpronosPlayBot","https://mrxpronos-play.cinecanaux-xpronos.workers.dev/telegram/webhook","commands",details,Date.now()).run();
}

export default {async fetch(request,env,ctx){const u=new URL(request.url),p=u.pathname;try{
 if(p==="/"||p==="/index.html")return page();
 if(p==="/api/health"){let bot_username=null,telegram_token_valid=false;try{if(env.BOT_TOKEN){const reply=await fetch("https://api.telegram.org/bot"+env.BOT_TOKEN+"/getMe");const result=await reply.json();telegram_token_valid=result.ok===true;bot_username=telegram_token_valid?result.result?.username||null:null}}catch{}return json({ok:true,app:"Mr XPRONOS Play",bot_connected:!!env.BOT_TOKEN,telegram_token_valid,bot_username,correct_bot:typeof bot_username==="string"&&bot_username.toLowerCase()==="mrxpronosplaybot",db_connected:!!env.DB,minimum_sync_interval_hours:12,payments_enabled:false,token_issued:false})}
 if(p==="/telegram/webhook"&&request.method==="POST"){
  if(!env.BOT_TOKEN||!env.WEBHOOK_SECRET||request.headers.get("X-Telegram-Bot-Api-Secret-Token")!==env.WEBHOOK_SECRET)return json({error:"Forbidden"},403);
  const update=await request.json();
  await telegramWebhook(env,update,u.origin,ctx);
  return json({ok:true});
 }
 if(!p.startsWith("/api/"))return json({error:"Not found"},404);
 if(request.method!=="GET"&&request.method!=="POST")return json({error:"Method not allowed"},405);
 const auth=await authenticate(request,env);if(!auth.user)return json({error:"Identification Telegram refusée : "+auth.reason,code:auth.reason},401);const user=auth.user;
 if(p==="/api/avatar"&&request.method==="GET"){
  const missing=()=>new Response(null,{status:404,headers:{"cache-control":"no-store","x-content-type-options":"nosniff"}});
  try{
   const api="https://api.telegram.org/bot"+env.BOT_TOKEN+"/";
   const pr=await fetch(api+"getUserProfilePhotos?user_id="+encodeURIComponent(user.id)+"&limit=1");
   if(!pr.ok)return missing();
   const photos=await pr.json(),versions=photos?.result?.photos?.[0];
   if(!photos?.ok||!Array.isArray(versions)||!versions.length)return missing();
   const fileId=versions[versions.length-1]?.file_id;
   if(typeof fileId!=="string"||!fileId)return missing();
   const fr=await fetch(api+"getFile?file_id="+encodeURIComponent(fileId));
   if(!fr.ok)return missing();
   const f=await fr.json(),filePath=f?.result?.file_path;
   if(!f?.ok||typeof filePath!=="string"||!/^photos\/[a-zA-Z0-9_./-]+$/.test(filePath)||filePath.includes(".."))return missing();
   const image=await fetch("https://api.telegram.org/file/bot"+env.BOT_TOKEN+"/"+filePath);
   if(!image.ok)return missing();
   const type=(image.headers.get("content-type")||"").split(";")[0].trim().toLowerCase();
   if(!["image/jpeg","image/png","image/webp"].includes(type))return missing();
   if(Number(image.headers.get("content-length")||0)>2000000)return missing();
   const bytes=await image.arrayBuffer();
   if(!bytes.byteLength||bytes.byteLength>2000000)return missing();
   return new Response(bytes,{status:200,headers:{"content-type":type,"cache-control":"private, no-store","x-content-type-options":"nosniff","cross-origin-resource-policy":"same-origin"}});
  }catch{return missing()}
 }
 let player=await ensurePlayer(env,user);
 if(p==="/api/game-features"&&request.method==="GET")return json({features:await getGameFeatures(env)});
 if(p==="/api/missions"&&request.method==="GET")return json({missions:await missionStatus(env,player)});
 if(p==="/api/missions/claim"&&request.method==="POST"){
  let payload;try{payload=await request.json()}catch{return json({error:"JSON_INVALIDE"},400)}
  const result=await awardPlayMission(env,player,String(payload?.mission_key||""));
  if(!result.ok)return json({error:result.reason,code:result.error},result.status);
  return json(result);
 }
 if(p==="/api/bootstrap"&&request.method==="GET"){
  const now=Date.now(), plans={},base=Math.floor(now/DAY)*DAY;
  for(let i=0;i<15;i++){const d=dateOf(base+i*DAY);plans[d]=(await wheelOutcome(env,user.id,d)).key}
  const [w,dc]=await Promise.all([env.DB.prepare("SELECT day FROM wheel_claims WHERE user_id=? AND day>=?").bind(user.id,dateOf(now-14*DAY)).all(),env.DB.prepare("SELECT day FROM daily_claims WHERE user_id=? AND day>=?").bind(user.id,dateOf(now-14*DAY)).all()]);
  return json({user:player,telegram_photo_url:auth.user.photoUrl||"",game_features:await getGameFeatures(env),missions:await missionStatus(env,player),wheel_plans:plans,wheel_claims:w.results.map(x=>x.day),daily_claims:dc.results.map(x=>x.day),server_time:now});
 }
 if(p==="/api/sync"&&request.method==="POST"){
  let body;try{body=await request.json()}catch{return json({error:"JSON invalide"},400)}
  const now=Date.now(),batch=String(body.batch_id||""),taps=Number(body.taps);
  if(!/^[\w-]{16,100}$/.test(batch)||!Number.isInteger(taps)||taps<0||taps>20000)return json({error:"Lot de tapotages invalide"},400);
  const previous=await env.DB.prepare("SELECT xp_awarded FROM sync_receipts WHERE user_id=? AND batch_id=?").bind(user.id,batch).first();
  if(previous)return json({ok:true,duplicate:true,xp_awarded:previous.xp_awarded,user:player});
  if(player.next_sync_ms>now)return json({error:"Prochaine synchronisation autorisée : "+new Date(player.next_sync_ms).toISOString(),next_sync_ms:player.next_sync_ms},429);
  const features=await getGameFeatures(env);
  if((!features.tap&&taps>0)||(!features.daily&&Array.isArray(body.daily_days)&&body.daily_days.length>0)||(!features.wheel&&Array.isArray(body.wheel_days)&&body.wheel_days.length>0))return json({error:"Un module du jeu est momentanément en pause. Les XP en attente restent conservés localement jusqu’à sa réactivation.",code:"GAME_PAUSED"},423);
  const elapsed=Math.max(0,now-Math.max(player.last_sync_ms,player.created_ms));
  const ceiling=Math.min(20000,500+Math.ceil(elapsed/3000));
  if(taps>ceiling)return json({error:"Tapotages incompatibles avec l'énergie régénérée. Vérification requise."},422);
  const daily=[...new Set(Array.isArray(body.daily_days)?body.daily_days:[])].filter(d=>validDay(d,now)&&Date.parse(d+"T00:00:00Z")>=Math.floor(player.created_ms/DAY)*DAY).slice(0,15);
  const wheel=[...new Set(Array.isArray(body.wheel_days)?body.wheel_days:[])].filter(d=>validDay(d,now)&&Date.parse(d+"T00:00:00Z")>=Math.floor(player.created_ms/DAY)*DAY).slice(0,15);
  const wExisting=new Set((await env.DB.prepare("SELECT day FROM wheel_claims WHERE user_id=? AND day>=?").bind(user.id,dateOf(now-14*DAY)).all()).results.map(x=>x.day));
  const dExisting=new Set((await env.DB.prepare("SELECT day FROM daily_claims WHERE user_id=? AND day>=?").bind(user.id,dateOf(now-14*DAY)).all()).results.map(x=>x.day));
  const newDaily=daily.filter(d=>!dExisting.has(d)),newWheel=wheel.filter(d=>!wExisting.has(d));
  const outcomes=[];for(const d of newWheel)outcomes.push({day:d,...await wheelOutcome(env,user.id,d)});
  const awarded=taps+newDaily.length*100+outcomes.reduce((n,x)=>n+x.xp,0);
  const ops=[
    env.DB.prepare("UPDATE players SET confirmed_xp=confirmed_xp+?,confirmed_taps=confirmed_taps+?,last_sync_ms=?,next_sync_ms=?,updated_ms=? WHERE user_id=? AND next_sync_ms<=? AND NOT EXISTS(SELECT 1 FROM sync_receipts WHERE user_id=? AND batch_id=?)").bind(awarded,taps,now,now+HALF,now,user.id,now,user.id,batch),
    env.DB.prepare("INSERT INTO sync_receipts(user_id,batch_id,taps,xp_awarded,wheel_count,created_ms) SELECT ?,?,?,?,?,? WHERE (SELECT last_sync_ms FROM players WHERE user_id=?)=?").bind(user.id,batch,taps,awarded,outcomes.length,now,user.id,now)
  ];
  for(const d of newDaily)ops.push(env.DB.prepare("INSERT OR IGNORE INTO daily_claims(user_id,day,xp_awarded,created_ms) SELECT ?,?,?,? WHERE (SELECT last_sync_ms FROM players WHERE user_id=?)=?").bind(user.id,d,100,now,user.id,now));
  for(const r of outcomes)ops.push(env.DB.prepare("INSERT OR IGNORE INTO wheel_claims(user_id,day,reward_key,xp_awarded,created_ms) SELECT ?,?,?,?,? WHERE (SELECT last_sync_ms FROM players WHERE user_id=?)=?").bind(user.id,r.day,r.key,r.xp,now,user.id,now));
  const result=await env.DB.batch(ops);
  player=await env.DB.prepare("SELECT * FROM players WHERE user_id=?").bind(user.id).first();
  if(!result[0]?.meta?.changes){const found=await env.DB.prepare("SELECT xp_awarded FROM sync_receipts WHERE user_id=? AND batch_id=?").bind(user.id,batch).first();if(found)return json({ok:true,duplicate:true,xp_awarded:found.xp_awarded,user:player});return json({error:"Synchronisation simultanée ou délai de 12 heures non écoulé",next_sync_ms:player.next_sync_ms},409)}
  return json({ok:true,duplicate:false,xp_awarded:awarded,user:player,wheel_outcomes:outcomes});
 }
 return json({error:"Route inconnue"},404)

 }catch(e){return json({error:"Erreur serveur",detail:env.DEV_MODE==="true"?String(e):undefined},500)}},
 async scheduled(event,env){await configureTelegramBot(env)}
}